//! TASK-097's official vectors, lifted from the RFC texts by a script (never
//! retyped): RFC 4231 (HMAC-SHA-256), RFC 5869 (HKDF), RFC 8439 (ChaCha20,
//! Poly1305, AEAD), draft-irtf-cfrg-xchacha-03 (HChaCha20, XChaCha20-Poly1305),
//! RFC 7748 (X25519), RFC 7693 (BLAKE2b), RFC 9106 (Argon2id).

pub fn hex(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}

